#!/usr/bin/env python3
"""Source-only release snapshots. Never deploy, restart, or submit jobs."""
import argparse
import gzip
import hashlib
import io
import json
import os
from pathlib import Path
import re
import tarfile
import tempfile

ROOT = Path(__file__).resolve().parents[2]
SKIP = {'node_modules', '.git', 'dist', 'ts-dist', '.cache', '__pycache__',
        '.pytest_cache', '.turbo', 'logs', 'results', 'jobs', 'state', 'inspire-results',
        '.venv', '.secrets', 'coverage', 'test-results', 'playwright-report',
        # Generated by the isolated frontend runtime builder.  It contains
        # machine-local absolute paths and minified bundles; source and runtime
        # releases are verified separately and must not be conflated.
        'live-web-assets'}
SUFFIXES = {'.py', '.ts', '.tsx', '.js', '.jsx', '.mjs', '.cjs', '.css', '.html',
            '.json', '.toml', '.md', '.sh', '.yml', '.yaml', '.svg', '.png', '.woff2',
            '.txt', '.patch', '.plist', '.sql', '.svelte', '.astro', '.lock'}
DENY = {'openscience.json', 'openscience_ligand_validation.json', 'auth.json'}
SECRET = re.compile(rb'(?:sk-[A-Za-z0-9_-]{24,}|-----BEGIN (?:RSA |OPENSSH |EC )?PRIVATE KEY-----\s+[A-Za-z0-9+/=]{40,})')
LIMIT = 256 * 1024 * 1024


def canonical(value):
    return json.dumps(value, sort_keys=True, ensure_ascii=False, separators=(',', ':')).encode()


def sha(data):
    return hashlib.sha256(data).hexdigest()


def safe(name):
    return bool(name) and not name.startswith('/') and not any(
        part in ('', '.', '..') for part in name.split('/')) and '\\' not in name


def collect(root, registry):
    paths = set()
    excluded = set(registry.get('source_exclude', []))
    if any(not isinstance(name, str) or not safe(name) for name in excluded):
        raise ValueError('Invalid excluded source path')
    for relative in registry['source_roots']:
        if not safe(relative):
            raise ValueError('Invalid source root')
        folder = root / relative
        if not folder.is_dir() or folder.is_symlink():
            raise ValueError('Missing or symlink source root: ' + relative)
        for current, dirs, files in os.walk(folder, followlinks=False):
            dirs[:] = sorted(d for d in dirs if d not in SKIP and not d.startswith('dist-') and not (Path(current) / d).is_symlink())
            for name in files:
                if name in DENY or name.startswith(('.env', '.runtime-')) or name.endswith('.provider.json'):
                    continue
                path = Path(current) / name
                if path.suffix in SUFFIXES or name in {'LICENSE', 'NOTICE', 'Dockerfile', 'Makefile'}:
                    if not path.is_symlink():
                        paths.add(path)
    for relative in registry['source_files']:
        if not safe(relative):
            raise ValueError('Invalid source file')
        if Path(relative).name.startswith('.runtime-'):
            raise ValueError('Generated runtime file cannot be registered as source: ' + relative)
        paths.add(root / relative)
    contents = {}
    total = 0
    for path in sorted(paths):
        name = path.relative_to(root).as_posix()
        if name in excluded:
            continue
        if path.is_symlink() or not path.is_file() or not path.resolve().is_relative_to(root.resolve()):
            raise ValueError('Missing or unsafe source: ' + name)
        total += path.stat().st_size
        if total > LIMIT:
            raise ValueError('Source snapshot exceeds 256 MiB')
        data = path.read_bytes()
        if SECRET.search(data):
            # Only the filename is reported; never print the matching credential.
            raise ValueError('Credential-like content: ' + name)
        contents[name] = data
    # Only explicitly registered internal aliases may be materialized in an
    # archive. Unregistered symlinks remain excluded; no outside source is read.
    for name, target in registry.get('source_links', {}).items():
        if not safe(name) or not safe(target) or name in contents or target not in contents:
            raise ValueError('Invalid registered source link: ' + name)
        link = root / name
        if not link.is_symlink() or link.resolve() != (root / target).resolve():
            raise ValueError('Registered source link changed: ' + name)
        total += len(contents[target])
        if total > LIMIT:
            raise ValueError('Source snapshot exceeds 256 MiB')
        contents[name] = contents[target]
    return contents


def build(root, output):
    registry = json.loads((root / 'ops/release/components.json').read_text())
    files = collect(root, registry)
    manifest = {'schema': 1, 'kind': 'source-snapshot-not-runtime',
                'files': {name: sha(data) for name, data in sorted(files.items())}}
    identity = sha(canonical(manifest))
    output.mkdir(parents=True, exist_ok=True)
    archive = output / (identity + '.tar.gz')
    if archive.exists():
        verify(archive)
        return archive
    # Stage fully before publishing; no half-written archive on failure.
    handle, temporary = tempfile.mkstemp(prefix='.source-', dir=output)
    try:
        with os.fdopen(handle, 'wb') as raw:
            with gzip.GzipFile(fileobj=raw, mode='wb', filename='', mtime=0) as zipped:
                with tarfile.open(fileobj=zipped, mode='w') as tar:
                    for name, data in sorted({**files, 'manifest.json': canonical(manifest)}.items()):
                        entry = tarfile.TarInfo(name)
                        entry.size = len(data)
                        entry.mode = 0o444
                        tar.addfile(entry, io.BytesIO(data))
        # Exclusive publication: never replace another release.
        os.link(temporary, archive)
    finally:
        os.unlink(temporary)
    verify(archive)
    return archive


def verify(archive):
    found = {}
    manifest = None
    total = 0
    with tarfile.open(archive, 'r:gz') as tar:
        for entry in tar:
            if not safe(entry.name) or not entry.isfile() or entry.name in found:
                raise ValueError('Invalid archive member')
            total += entry.size
            if total > LIMIT or len(found) > 30000:
                raise ValueError('Archive exceeds limits')
            data = tar.extractfile(entry).read()
            found[entry.name] = sha(data)
            if entry.name == 'manifest.json':
                manifest = json.loads(data)
    found.pop('manifest.json', None)
    if not manifest or manifest.get('files') != found:
        raise ValueError('Source hashes differ')
    identity = sha(canonical(manifest))
    if archive.name != identity + '.tar.gz':
        raise ValueError('Release identity differs')
    return {'release_id': identity, 'files': len(found), 'archive': str(archive)}


if __name__ == '__main__':
    parser = argparse.ArgumentParser(description=__doc__)
    commands = parser.add_subparsers(dest='command', required=True)
    create = commands.add_parser('build')
    create.add_argument('--output', type=Path, default=ROOT / 'releases/source')
    check = commands.add_parser('verify')
    check.add_argument('archive', type=Path)
    args = parser.parse_args()
    archive = build(ROOT, args.output) if args.command == 'build' else args.archive
    print(json.dumps(verify(archive), ensure_ascii=False, indent=2))
